async function getStudioProvisioningDrafts() {
  await ensureStoreProvisioningDraftSchema();
  const db = await getDb();
  if (!db) return [...DEMO_PROVISIONING_DRAFTS].sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime());
  return db.select().from(storeProvisioningDrafts2).orderBy(desc(storeProvisioningDrafts2.updatedAt));
}
function parseStudioStoreCopySelection(value) {
  if (!value?.trim()) return null;
  try {
    const selection = normalizeStudioStoreCopySelection(JSON.parse(value));
    return hasStudioStoreCopyScope(selection) ? selection : null;
  } catch {
    return null;
  }
}
