async function bulkCreateAliExpressDrafts(categoryId, urls, storeId) {
  let created = 0;
  const skipped = [];
  for (const url of urls) {
    const match = url.match(/\/item\/(\d{6,})\.html/) || url.match(/[?&]productId=(\d{6,})/) || url.match(/(\d{10,})/);
    const pid = match ? match[1] : null;
    if (!pid) {
      skipped.push(url);
      continue;
    }
    const slug = `ali-${pid}-${Date.now().toString(36)}${Math.floor(Math.random() * 1e3)}`;
    try {
      await createProduct({
        categoryId,
        name: `Import AliExpress ${pid}`,
        slug,
        price: 0,
        stock: 0,
        featured: 0,
        status: "draft",
        supplier: "AliExpress",
        supplierUrl: url,
        supplierProductId: pid,
        categoryIds: [categoryId]
      }, storeId);
      created++;
    } catch {
      skipped.push(url);
    }
  }
  return { created, skipped };
}
