async function applyDraftSeoUpdates(updates, storeId) {
  await ensureStoreCatalogScopeSchema();
  const db = await getDb();
  if (!db) throw new Error("Base de donn\xE9es non disponible");
  const effectiveStoreId = storeId ?? await getPrimaryStoreId();
  const uniqueUpdates = Array.from(new Map(updates.map((update) => [update.id, update])).values());
  if (uniqueUpdates.length === 0) return { updated: 0, archived: 0, skipped: 0 };
  const existing = await db.select({ id: products2.id, status: products2.status }).from(products2).where(and2(eq2(products2.storeId, effectiveStoreId), inArray(products2.id, uniqueUpdates.map((update) => update.id))));
  const statusById = new Map(existing.map((product) => [product.id, product.status]));
  let updated = 0;
  let archived = 0;
  let skipped = 0;
  for (const update of uniqueUpdates) {
    if (statusById.get(update.id) !== "draft") {
      skipped += 1;
      continue;
    }
    if (update.archive) {
      await db.update(products2).set({ status: "archived" }).where(and2(eq2(products2.storeId, effectiveStoreId), eq2(products2.id, update.id), eq2(products2.status, "draft")));
      archived += 1;
      continue;
    }
    if (!update.name || !update.description || !update.longDescription) {
      skipped += 1;
      continue;
    }
    await db.update(products2).set({
      name: update.name.trim(),
      description: update.description.trim(),
      longDescription: update.longDescription.trim()
    }).where(and2(eq2(products2.storeId, effectiveStoreId), eq2(products2.id, update.id), eq2(products2.status, "draft")));
    updated += 1;
  }
  return { updated, archived, skipped };
}
async function applyDraftCsvEditorialUpdates(updates, storeId) {
  await ensureStoreCatalogScopeSchema();
  const db = await getDb();
  if (!db) throw new Error("Base de donn\xE9es non disponible");
  const effectiveStoreId = storeId ?? await getPrimaryStoreId();
  const uniqueUpdates = Array.from(new Map(updates.map((update) => [update.id, update])).values());
  if (uniqueUpdates.length === 0) {
    return { updated: 0, missing: 0, skippedNotDraft: 0, skippedEmpty: 0 };
  }
  const existing = await db.select({ id: products2.id, status: products2.status }).from(products2).where(and2(eq2(products2.storeId, effectiveStoreId), inArray(products2.id, uniqueUpdates.map((update) => update.id))));
  const statusById = new Map(existing.map((product) => [product.id, product.status]));
  let updated = 0;
  let missing = 0;
  let skippedNotDraft = 0;
  let skippedEmpty = 0;
  for (const update of uniqueUpdates) {
    const patch = {};
    if (update.name?.trim()) patch.name = update.name.trim();
    if (update.description?.trim()) patch.description = update.description.trim();
    if (update.longDescription?.trim()) patch.longDescription = update.longDescription.trim();
    if (Object.keys(patch).length === 0) {
      skippedEmpty += 1;
      continue;
    }
    const currentStatus = statusById.get(update.id);
    if (currentStatus == null) {
      missing += 1;
      continue;
    }
    if (currentStatus !== "draft") {
      skippedNotDraft += 1;
      continue;
    }
    await db.update(products2).set(patch).where(and2(eq2(products2.storeId, effectiveStoreId), eq2(products2.id, update.id), eq2(products2.status, "draft")));
    await markProductTranslationsStale(update.id, effectiveStoreId);
    updated += 1;
  }
  return { updated, missing, skippedNotDraft, skippedEmpty };
}
