async function recordOrderDecision(input) {
  await ensureStoreRelationshipScopeSchema();
  const db = await getDb();
  if (!db) throw new Error("Database not available");
  const effectiveStoreId = input.storeId ?? await getPrimaryStoreId();
  const order = await db.select({ id: orders2.id, status: orders2.status, paymentStatus: orders2.paymentStatus, paymentMethod: orders2.paymentMethod }).from(orders2).where(and2(eq2(orders2.storeId, effectiveStoreId), eq2(orders2.id, input.orderId))).limit(1);
  if (!order[0]) throw new Error("ORDER_NOT_FOUND");
  if (input.action === "accepted") {
    const cashOnDelivery = order[0].paymentMethod === ALGERIA_CASH_ON_DELIVERY_PAYMENT_METHOD;
    if (order[0].paymentStatus !== "paid" && !cashOnDelivery) throw new Error("ORDER_NOT_PAID");
    if (order[0].status === "processing") {
      const existing = await db.select({ id: orderDecisions2.id }).from(orderDecisions2).where(and2(eq2(orderDecisions2.storeId, effectiveStoreId), eq2(orderDecisions2.orderId, input.orderId), eq2(orderDecisions2.action, "accepted"))).limit(1);
      if (existing[0]) return { success: true, supplierOrderCreated: false, paymentRefunded: false, alreadyAccepted: true };
    } else {
      if (order[0].status !== "pending") throw new Error("ORDER_NOT_PENDING");
      await db.update(orders2).set({ status: "processing" }).where(and2(eq2(orders2.storeId, effectiveStoreId), eq2(orders2.id, input.orderId)));
    }
  }
  if (input.action === "rejected") {
    if (order[0].status === "shipped" || order[0].status === "delivered") throw new Error("ORDER_ALREADY_FULFILLED");
    if (order[0].status !== "cancelled") {
      await db.transaction(async (tx) => {
        const cancelled = await tx.update(orders2).set({ status: "cancelled" }).where(and2(
          eq2(orders2.storeId, effectiveStoreId),
          eq2(orders2.id, input.orderId),
          ne(orders2.status, "cancelled")
        ));
        if (affectedRows(cancelled) !== 1) return;
        if (order[0].paymentMethod === ALGERIA_CASH_ON_DELIVERY_PAYMENT_METHOD && order[0].paymentStatus === "unpaid") {
          await releaseStoredCheckoutStock(tx, effectiveStoreId, input.orderId);
        }
      });
    }
  }
  await db.insert(orderDecisions2).values({
    storeId: effectiveStoreId,
    orderId: input.orderId,
    action: input.action,
    reason: input.reason?.trim() || null,
    actorUserId: input.actorUserId
  });
  return { success: true, supplierOrderCreated: false, paymentRefunded: false };
}
async function confirmAlgeriaCashOnDeliveryCollection(input) {
  await ensureStoreRelationshipScopeSchema();
  const db = await getDb();
  if (!db) throw new Error("Database not available");
  const [order] = await db.select({ id: orders2.id, status: orders2.status, paymentStatus: orders2.paymentStatus, paymentMethod: orders2.paymentMethod }).from(orders2).where(and2(eq2(orders2.storeId, input.storeId), eq2(orders2.id, input.orderId))).limit(1);
  if (!order) throw new Error("ORDER_NOT_FOUND");
  if (order.paymentMethod !== ALGERIA_CASH_ON_DELIVERY_PAYMENT_METHOD) throw new Error("ORDER_PAYMENT_METHOD_INVALID");
  if (order.paymentStatus === "paid") return { success: true, alreadyCollected: true };
  if (order.status !== "delivered") throw new Error("CASH_ON_DELIVERY_NOT_DELIVERED");
  const update = await db.update(orders2).set({ paymentStatus: "paid" }).where(and2(
    eq2(orders2.storeId, input.storeId),
    eq2(orders2.id, input.orderId),
    eq2(orders2.paymentMethod, ALGERIA_CASH_ON_DELIVERY_PAYMENT_METHOD),
    eq2(orders2.paymentStatus, "unpaid"),
    eq2(orders2.status, "delivered")
  ));
  return { success: true, alreadyCollected: affectedRows(update) !== 1 };
}
