async function createOrder(userId, data, storeId) {
  await ensureStoreRelationshipScopeSchema();
  const db = await getDb();
  if (!db) throw new Error("Database not available");
  const effectiveStoreId = storeId ?? await getPrimaryStoreId();
  const cart = await getCart(userId, effectiveStoreId);
  if (!cart || cart.items.length === 0) throw new Error("Cart is empty");
  const subtotal = cart.items.reduce((sum2, item) => sum2 + item.price * item.quantity, 0);
  const promotionResult = data.promoCode ? await validatePromotion(data.promoCode, subtotal, {
    userId,
    cartItems: cart.items.map((item) => ({ productId: item.productId, price: item.price, quantity: item.quantity })),
    storeId: effectiveStoreId
  }) : null;
  const discountAmount = promotionResult?.discountAmount ?? 0;
  const totalAmount = subtotal - discountAmount;
  const result2 = await db.insert(orders2).values({
    storeId: effectiveStoreId,
    userId,
    totalAmount,
    shippingAddress: data.shippingAddress,
    billingAddress: data.billingAddress || data.shippingAddress,
    paymentMethod: data.paymentMethod,
    promotionId: promotionResult?.promotion.id ?? null,
    discountAmount,
    status: "pending",
    paymentStatus: "unpaid"
  });
  const orderId = result2[0].insertId;
  const orderItemValues = cart.items.map((item) => ({
    storeId: effectiveStoreId,
    orderId,
    productId: item.productId,
    quantity: item.quantity,
    priceAtPurchase: item.price
  }));
  await db.insert(orderItems2).values(orderItemValues);
  if (promotionResult) {
    await recordPromotionRedemption({ promotionId: promotionResult.promotion.id, userId, orderId, discountAmount, storeId: effectiveStoreId });
  }
  await clearCart(userId, effectiveStoreId);
  return { id: orderId };
}
