async function validatePromotion(code, orderAmount, opts) {
  await ensureStoreRelationshipScopeSchema();
  const effectiveStoreId = opts?.storeId ?? await getPrimaryStoreId();
  const promotion = await getPromotionByCode(code, effectiveStoreId);
  if (!promotion || !promotion.active) throw new Error("Code promo invalide ou d\xE9sactiv\xE9");
  const now2 = Date.now();
  if (promotion.startsAt && new Date(promotion.startsAt).getTime() > now2) throw new Error("Ce code promo n'est pas encore actif");
  if (promotion.expiresAt && new Date(promotion.expiresAt).getTime() < now2) throw new Error("Ce code promo a expir\xE9");
  if (promotion.maxUses !== null && promotion.usedCount >= promotion.maxUses) throw new Error("La limite d'utilisation de ce code est atteinte");
  if (promotion.minOrderAmount !== null && orderAmount < promotion.minOrderAmount) throw new Error(`Montant minimum requis : ${(promotion.minOrderAmount / 100).toFixed(2)} CHF`);
  if (promotion.scope === "first_order") {
    if (!opts?.userId) throw new Error("Connectez-vous pour utiliser ce code r\xE9serv\xE9 au premier achat");
    const paidOrders = await countUserPaidOrders(opts.userId, effectiveStoreId);
    if (paidOrders > 0) throw new Error("Ce code est r\xE9serv\xE9 \xE0 votre premi\xE8re commande");
  }
  if (promotion.perUserLimit !== null && promotion.perUserLimit > 0) {
    if (!opts?.userId) throw new Error("Connectez-vous pour utiliser ce code");
    const used = await countUserPromotionRedemptions(promotion.id, opts.userId, effectiveStoreId);
    if (used >= promotion.perUserLimit) throw new Error("Vous avez d\xE9j\xE0 utilis\xE9 ce code le nombre de fois autoris\xE9");
  }
  let discountBase = orderAmount;
  if (promotion.scope === "category" && promotion.categoryId) {
    if (!opts?.cartItems || opts.cartItems.length === 0) throw new Error("Ce code s'applique \xE0 une cat\xE9gorie pr\xE9cise du panier");
    const productIds = opts.cartItems.map((item) => item.productId);
    const eligibleProductIds = /* @__PURE__ */ new Set();
    for (const productId of productIds) {
      const categoryIds = await getProductCategoryIds(productId, effectiveStoreId);
      if (categoryIds.includes(promotion.categoryId)) eligibleProductIds.add(productId);
    }
    discountBase = opts.cartItems.filter((item) => eligibleProductIds.has(item.productId)).reduce((sum2, item) => sum2 + item.price * item.quantity, 0);
    if (discountBase <= 0) throw new Error("Aucun article du panier n'est \xE9ligible \xE0 ce code");
  }
  if (promotion.scope === "products") {
    if (!opts?.cartItems || opts.cartItems.length === 0) throw new Error("Ce code s'applique \xE0 des produits pr\xE9cis du panier");
    const targetProductIds = parsePromotionTargetProductIds(promotion.productIds);
    discountBase = getPromotionTargetProductsSubtotal(opts.cartItems, targetProductIds);
    if (discountBase <= 0) throw new Error("Aucun article du panier n'est \xE9ligible \xE0 ce code");
  }
  const discountAmount = promotion.type === "percent" ? Math.min(discountBase, Math.floor(discountBase * promotion.value / 100)) : Math.min(discountBase, promotion.value);
  return { promotion, discountAmount, totalAmount: orderAmount - discountAmount };
}
