function normalizeCashOnDeliveryAddress(input) {
  const text4 = (value, maxLength) => typeof value === "string" ? value.replace(/[\u0000-\u001F\u007F]/g, " ").replace(/\s+/g, " ").trim().slice(0, maxLength) : "";
  const address = {
    source: ALGERIA_CASH_ON_DELIVERY_PAYMENT_METHOD,
    name: text4(input.name, 160),
    phone: text4(input.phone, 60),
    line1: text4(input.line1, 240),
    line2: text4(input.line2, 240) || null,
    city: text4(input.city, 120),
    postalCode: text4(input.postalCode, 32),
    countryCode: "DZ"
  };
  if (!address.name || !address.phone || !address.line1 || !address.city || !address.postalCode) {
    throw new Error("CASH_ON_DELIVERY_ADDRESS_INCOMPLETE");
  }
  return address;
}
