async function releaseExpiredStripePendingOrder(input) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");
  const mode = input.mode ?? "test";
  return await db.transaction(async (tx) => {
    const [order] = await tx.select({ id: orders2.id, storeId: orders2.storeId }).from(orders2).where(and2(
      eq2(orders2.stripeSessionId, input.sessionId),
      eq2(orders2.stripeConnectedAccountId, input.stripeAccountId),
      eq2(orders2.paymentMethod, `stripe_connect_${mode}`),
      eq2(orders2.paymentStatus, "unpaid"),
      eq2(orders2.status, "pending")
    )).limit(1);
    if (!order) return { released: false, releasedLines: 0 };
    const result2 = await tx.update(orders2).set({ status: "cancelled" }).where(and2(
      eq2(orders2.id, order.id),
      eq2(orders2.storeId, order.storeId),
      eq2(orders2.paymentStatus, "unpaid"),
      eq2(orders2.status, "pending")
    ));
    if (affectedRows(result2) !== 1) return { released: false, releasedLines: 0 };
    const release = await releaseStoredCheckoutStock(tx, order.storeId, order.id);
    return { released: true, ...release };
  });
}
async function releaseElapsedCheckoutReservations(storeId) {
  const db = await getDb();
  if (!db) return;
  const cutoff = new Date(Date.now() - 33 * 60 * 1e3);
  const candidates = await db.select({ id: orders2.id, stripeSessionId: orders2.stripeSessionId, stripeConnectedAccountId: orders2.stripeConnectedAccountId, paymentMethod: orders2.paymentMethod }).from(orders2).where(and2(
    eq2(orders2.storeId, storeId),
    eq2(orders2.status, "pending"),
    eq2(orders2.paymentStatus, "unpaid"),
    lt(orders2.createdAt, cutoff)
  )).limit(3);
  for (const candidate of candidates) {
    if (!candidate.stripeSessionId || !candidate.stripeConnectedAccountId || !["stripe_connect_test", "stripe_connect_live"].includes(candidate.paymentMethod || "")) continue;
    const mode = candidate.paymentMethod === "stripe_connect_live" ? "live" : "test";
    try {
      const expired = await verifyStaleStripeCheckout({ orderId: candidate.id, storeId, mode, sessionId: candidate.stripeSessionId, stripeAccountId: candidate.stripeConnectedAccountId });
      if (expired) await releaseExpiredStripePendingOrder({ mode, sessionId: candidate.stripeSessionId, stripeAccountId: candidate.stripeConnectedAccountId });
    } catch (error) {
      console.warn("[checkout-stock] Stripe expiry could not be verified", { storeId, orderId: candidate.id, reason: error instanceof Error ? error.name : "UNKNOWN" });
    }
  }
}
