        faviconUrl: z4.union([z4.literal(""), visualUrl]),
        highlightEyebrow: z4.string().trim().max(120),
        highlightTitle: z4.string().trim().min(2).max(180),
        highlightText: z4.string().trim().min(2).max(600),
        highlightImageUrl: visualUrl,
        storyTitle: z4.string().trim().min(2).max(180),
        storyText: z4.string().trim().min(2).max(1e3),
