// server/supplierHubRouter.ts
var providerEnum = z13.enum(["cjdropshipping", "aliexpress", "printful", "printify"]);
var supplierHubRouter = router({
  // 1. GESTION DES CONNEXIONS FOURNISSEURS (MULTI-TENANT)
  getConnections: storeOwnerProcedure.query(async ({ ctx }) => {
    return await getStoreSupplierConnections(ctx.store.id);
  }),
  saveConnection: storeOwnerProcedure.input(
    z13.object({
      provider: providerEnum,
      apiKey: z13.string().trim().min(4, "La cl\xE9 est requise."),
      accountLabel: z13.string().trim().max(100).optional()
    })
  ).mutation(async ({ ctx, input }) => {
    return await saveStoreSupplierConnection(
      ctx.store.id,
      input.provider,
      input.apiKey,
      input.accountLabel
    );
  }),
  removeConnection: storeOwnerProcedure.input(z13.object({ provider: providerEnum })).mutation(async ({ ctx, input }) => {
    return await removeStoreSupplierConnection(
      ctx.store.id,
      input.provider
    );
  }),
  testConnection: storeOwnerProcedure.input(z13.object({ provider: providerEnum })).mutation(async ({ ctx, input }) => {
    return await testStoreSupplierConnection(
      ctx.store.id,
      input.provider
    );
  }),
  // 2. RECHERCHE DE CATALOGUE & SOURCING
  searchCatalog: storeOwnerProcedure.input(
    z13.object({
      query: z13.string().default(""),
      provider: providerEnum.optional()
    })
  ).query(async ({ ctx, input }) => {
    return await searchSupplierCatalog(
      ctx.store.id,
      input.query,
      input.provider
    );
  }),
  importUrl: storeOwnerProcedure.input(z13.object({ url: z13.string().trim().url("Indiquez une URL valide.") })).mutation(async ({ ctx, input }) => {
    return await importSupplierProductByUrl(ctx.store.id, input.url);
  }),
  // 3. FILE DE BROUILLONS & ATELIER D'ÉDITION
  getDrafts: storeOwnerProcedure.query(async ({ ctx }) => {
    return await getSupplierProductDrafts(ctx.store.id);
  }),
  stageCatalogItemToDraft: storeOwnerProcedure.input(
    z13.object({
      provider: providerEnum,
      supplierProductId: z13.string(),
      supplierUrl: z13.string(),
      title: z13.string(),
      thumbnail: z13.string(),
      sourcePriceCents: z13.number(),
      supplierShippingEstimateCents: z13.number(),
      stock: z13.number(),
      supplierName: z13.string(),
      originCountry: z13.string(),
      estimatedDeliveryDays: z13.number()
    })
  ).mutation(async ({ ctx, input }) => {
    const defaultSellingPrice = Math.round((input.sourcePriceCents + input.supplierShippingEstimateCents) * 2.2);
    const profit = defaultSellingPrice - (input.sourcePriceCents + input.supplierShippingEstimateCents);
    const marginPercent = Math.round(profit / (input.sourcePriceCents + input.supplierShippingEstimateCents) * 100);
    return await createSupplierProductDraft(ctx.store.id, {
      provider: input.provider,
      supplierProductId: input.supplierProductId,
      supplierUrl: input.supplierUrl,
      title: input.title,
      description: `Produit approvisionn\xE9 depuis ${input.supplierName} (${input.originCountry}). D\xE9lai de livraison estim\xE9 : ${input.estimatedDeliveryDays} jours ouvr\xE9s.`,
      categoryName: "Catalogue Sourcing",
      sourcePriceCents: input.sourcePriceCents,
      sourceCurrency: "CHF",
      shippingCostCents: input.supplierShippingEstimateCents,
      sellingPriceCents: defaultSellingPrice,
      marginPercent,
      profitCents: profit,
      stock: input.stock,
      images: [input.thumbnail],
      selectedImages: [input.thumbnail],
      variants: [
        {
          id: `var-${Date.now()}`,
          name: "Mod\xE8le Standard",
          sku: `${input.provider.slice(0, 3).toUpperCase()}-${Math.floor(1e3 + Math.random() * 9e3)}`,
          sourcePriceCents: input.sourcePriceCents,
          stock: input.stock,
          options: {}
        }
      ],
      deliveryDaysMin: Math.max(2, input.estimatedDeliveryDays - 2),
      deliveryDaysMax: input.estimatedDeliveryDays + 3,
      shippingCountry: "Europe",
      status: "draft"
    });
  }),
  updateDraft: storeOwnerProcedure.input(
    z13.object({
      draftId: z13.string(),
      title: z13.string().min(1).optional(),
      description: z13.string().optional(),
      categoryName: z13.string().optional(),
      sellingPriceCents: z13.number().int().min(0).optional(),
      sourcePriceCents: z13.number().int().min(0).optional(),
      shippingCostCents: z13.number().int().min(0).optional(),
      selectedImages: z13.array(z13.string()).optional(),
      status: z13.enum(["draft", "ready", "published", "archived"]).optional()
    })
  ).mutation(async ({ ctx, input }) => {
    const { draftId, ...changes } = input;
    if (changes.sellingPriceCents != null || changes.sourcePriceCents != null || changes.shippingCostCents != null) {
      const drafts = await getSupplierProductDrafts(ctx.store.id);
      const current = drafts.find((d) => d.id === draftId);
      if (current) {
        const selling = changes.sellingPriceCents ?? current.sellingPriceCents;
        const cost = changes.sourcePriceCents ?? current.sourcePriceCents;
        const shipping = changes.shippingCostCents ?? current.shippingCostCents;
        const totalCost = cost + shipping;
        const profit = selling - totalCost;
        const margin = totalCost > 0 ? Math.round(profit / totalCost * 100) : 0;
        changes.profitCents = profit;
        changes.marginPercent = margin;
      }
    }
    return await updateSupplierProductDraft(ctx.store.id, draftId, changes);
  }),
  deleteDraft: storeOwnerProcedure.input(z13.object({ draftId: z13.string() })).mutation(async ({ ctx, input }) => {
    return await deleteSupplierProductDraft(ctx.store.id, input.draftId);
  }),
  // 4. PUBLICATION AU CATALOGUE DE LA BOUTIQUE
  publishDraft: storeOwnerProcedure.input(
    z13.object({
      draftId: z13.string(),
      categoryId: z13.number().int().optional()
    })
  ).mutation(async ({ ctx, input }) => {
    try {
      return await publishSupplierProductDraft(ctx.store.id, input.draftId, input.categoryId);
    } catch (error) {
      throw new TRPCError13({
        code: "INTERNAL_SERVER_ERROR",
        message: error.message || "Impossible de publier ce produit."
      });
    }
  })
});

