init_db();
async function executeShopifyMigration(storeId, products3) {
  let createdCount = 0;
  let updatedCount = 0;
  let categoriesCreated = 0;
  const existingCategories = await getAllCategories(storeId);
  const categoryMap = /* @__PURE__ */ new Map();
  for (const cat of existingCategories) {
    categoryMap.set(cat.name.toLowerCase(), cat.id);
  }
  for (const prod of products3) {
    const catName = prod.categoryName.trim() || "Catalogue G\xE9n\xE9ral";
    let categoryId = categoryMap.get(catName.toLowerCase());
    if (!categoryId) {
      categoryId = existingCategories[0]?.id || 1;
      categoryMap.set(catName.toLowerCase(), categoryId);
      categoriesCreated++;
    }
    const slug = prod.handle.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
    try {
      await createProduct(
        {
          categoryId,
          name: prod.title,
          slug: `${slug}-${Math.floor(1e3 + Math.random() * 9e3)}`,
          description: prod.bodyHtml ? prod.bodyHtml.replace(/<[^>]*>/g, " ").slice(0, 300) : prod.title,
          longDescription: prod.bodyHtml || prod.title,
          price: prod.priceCents,
          originalPrice: prod.originalPriceCents || null,
          stock: prod.stock,
          status: "active",
          featured: 0,
          images: prod.images.length > 0 ? prod.images : ["https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800"],
          supplier: prod.vendor || "Shopify Migration",
          supplierProductId: prod.handle,
          deliveryProfiles: []
        },
        storeId
      );
      createdCount++;
    } catch (err) {
      console.warn(`[ShopifyMigration] Product creation error for "${prod.title}":`, err);
    }
  }
  return {
    createdCount,
    updatedCount,
    categoriesCreated
  };
}
async function generateFullCatalogueCsv(storeId) {
  const products3 = await getAllProducts(storeId);
  const categories3 = await getAllCategories(storeId);
  const catMap = new Map(categories3.map((c) => [c.id, c.name]));
  const { getProductImagesForProducts: getProductImagesForProducts2 } = await Promise.resolve().then(() => (init_db(), db_exports));
  const imagesMap = await getProductImagesForProducts2(products3.map((p) => p.id), storeId);
  const headers = [
    "ID",
    "Titre",
    "Slug",
    "Cat\xE9gorie",
    "Prix (CHF)",
    "Prix d'origine (CHF)",
    "Stock",
    "Statut",
    "Image Principale",
    "Fournisseur"
  ];
  const rows = [headers.join(",")];
  for (const p of products3) {
    const catName = catMap.get(p.categoryId) || "G\xE9n\xE9ral";
    const priceChf = (p.price / 100).toFixed(2);
    const origPriceChf = p.originalPrice ? (p.originalPrice / 100).toFixed(2) : "";
    const imgs = imagesMap.get(p.id) || [];
    const mainImg = imgs.length > 0 ? imgs[0].imageUrl : "";
    const row = [
      p.id,
      `"${p.name.replace(/"/g, '""')}"`,
      p.slug,
      `"${catName.replace(/"/g, '""')}"`,
      priceChf,
      origPriceChf,
      p.stock,
      p.status,
      `"${mainImg}"`,
      `"${p.supplier || "Boutique"}"`
    ];
    rows.push(row.join(","));
  }
  return rows.join("\n");
}

