function generateReferralCode(userEmail) {
  const prefix = userEmail.split("@")[0].replace(/[^a-zA-Z0-9]/g, "").toUpperCase().slice(0, 5);
  const random = Math.floor(1e3 + Math.random() * 9e3);
  return `${prefix || "CLUB"}-${random}`;
}

// server/db/loyaltyProgramStorage.ts
var loyaltyConfigRegistry = /* @__PURE__ */ new Map();
var accountRegistry = /* @__PURE__ */ new Map();
async function getStoreLoyaltyConfig(storeId) {
  const existing = loyaltyConfigRegistry.get(storeId);
  if (existing) return existing;
  const defaultConfig = {
    storeId,
    pointsPerSpentCents: 1,
    // 1 point per 1 CHF
    centsPerRedeemedPoint: 5,
    // 100 points = 5.00 CHF discount
    minRedeemPoints: 50,
    referralRewardCents: 1e3,
    // 10.00 CHF discount
    enabled: true
  };
  loyaltyConfigRegistry.set(storeId, defaultConfig);
  return defaultConfig;
}
async function saveStoreLoyaltyConfig(storeId, input) {
  const current = await getStoreLoyaltyConfig(storeId);
  const updated = {
    ...current,
    ...input,
    storeId
  };
  loyaltyConfigRegistry.set(storeId, updated);
  return updated;
}
async function getCustomerLoyaltyAccount(storeId, userId, userEmail = "client@example.ch") {
  const key = `${storeId}:${userId}`;
  const existing = accountRegistry.get(key);
  if (existing) return existing;
  const account = {
    userId,
    storeId,
    pointsBalance: 120,
    // Initial welcome bonus points
    totalEarnedPoints: 120,
    referralCode: generateReferralCode(userEmail),
    referralCount: 1,
    totalReferralEarningsCents: 1e3
  };
  accountRegistry.set(key, account);
  return account;
}
async function redeemPointsForDiscount(storeId, userId, pointsToRedeem, userEmail = "client@example.ch") {
  const config = await getStoreLoyaltyConfig(storeId);
  if (!config.enabled) {
    throw new Error("Le programme de fid\xE9lit\xE9 n'est pas actif actuellement.");
  }
  const account = await getCustomerLoyaltyAccount(storeId, userId, userEmail);
  if (pointsToRedeem < config.minRedeemPoints) {
    throw new Error(`Minimum ${config.minRedeemPoints} points requis pour effectuer un \xE9change.`);
  }
  if (account.pointsBalance < pointsToRedeem) {
    throw new Error(`Solde insuffisant : vous disposez de ${account.pointsBalance} points.`);
  }
  const discountCents = pointsToRedeem * config.centsPerRedeemedPoint;
  account.pointsBalance -= pointsToRedeem;
  const key = `${storeId}:${userId}`;
  accountRegistry.set(key, account);
  const promoCode = `FIDELITE-${Math.floor(1e3 + Math.random() * 9e3)}`;
  return {
    success: true,
    promoCode,
    discountCents,
    remainingPoints: account.pointsBalance
  };
}

